import { readFileSync } from "node:fs";

import { expect, test, type Locator, type Page } from "@playwright/test";

import { mockLangGraphAPI } from "./utils/mock-api";

// Generated by the real synthetic export API. Backend tests independently verify
// the stored receipt, exact ZIP members and every archived member hash.
const fixture = JSON.parse(
  readFileSync(
    new URL("../fixtures/synthetic-authorized-export.json", import.meta.url),
    "utf8",
  ),
);
const receipt = fixture.receipt;
const base = `/api/evaluation/projects/${receipt.project_id}`;
const exportPath = `${base}/exports/${receipt.id}`;
const bundle = Buffer.from(fixture.bundle_base64, "base64");
const createLabel = "Create authorized configuration archive";
const reconcileLabel = "Reconcile the same export ID";
const downloadLabel = "Download viewed configuration ZIP";
const downloadConsent =
  "I confirm downloading this viewed configuration to my device for the declared recipient.";
const consents = [
  "I confirm this exact source, grant, recipient and tier.",
  "I separately authorize the selected data to leave the platform.",
  "I acknowledge external destination, load, output protection and retention controls remain separate responsibilities.",
];
function panel(page: Page) {
  return page.getByRole("region", {
    name: "Authorized QA configuration exports",
    exact: true,
  });
}
async function setup(page: Page) {
  mockLangGraphAPI(page, { threads: [] });
  // Keep the actual archived ID throughout PUT, receipt and ZIP; no fixture
  // document is re-labelled to claim a different binary was created.
  await page.addInitScript((id: string) => {
    const uuid = `${id.slice(0, 8)}-${id.slice(8, 12)}-${id.slice(12, 16)}-${id.slice(16, 20)}-${id.slice(20)}`;
    Object.defineProperty(Crypto.prototype, "randomUUID", {
      value: () => uuid,
    });
  }, receipt.id);
  const requests: string[] = [],
    forbidden: string[] = [];
  page.on("request", (request) => {
    if (
      /example\.test|\/gold(?:\?|$|\/)|\/reference-answers|\/api\/component-tests|\/api\/reports\/assistant/.test(
        request.url(),
      )
    )
      forbidden.push(request.url());
  });
  await page.route("**/api/evaluation/**", async (route) => {
    const request = route.request(),
      path = new URL(request.url()).pathname;
    requests.push(`${request.method()} ${path}`);
    if (path === "/api/evaluation/projects")
      return route.fulfill({
        json: {
          projects: [
            { id: receipt.project_id, name: "Synthetic export project" },
            { id: "p2", name: "Other project" },
          ],
        },
      });
    if (path.endsWith("/datasets"))
      return route.fulfill({ json: { datasets: [] } });
    if (path === `${base}/export-capabilities`)
      return route.fulfill({ json: fixture.capabilities });
    if (path === `${base}/plans/${receipt.plan_id}`)
      return route.fulfill({ json: fixture.plan });
    if (path === exportPath && request.method() === "PUT") {
      expect(request.postDataJSON()).toEqual(fixture.request);
      return route.fulfill({ json: receipt });
    }
    if (path === exportPath && request.method() === "GET")
      return route.fulfill({ json: receipt });
    if (path === `${exportPath}/bundle`) {
      const url = new URL(request.url());
      expect(request.method()).toBe("GET");
      expect(url.searchParams.get("viewed_receipt_hash")).toBe(
        receipt.receipt_hash,
      );
      expect(url.searchParams.get("confirm_download")).toBe("true");
      return route.fulfill({
        contentType: "application/zip",
        body: bundle,
        headers: {
          "x-devpilot-exporter": receipt.exporter,
          "x-devpilot-receipt-hash": receipt.receipt_hash,
          "cache-control": "private, no-store",
        },
      });
    }
    forbidden.push(`${request.method()} ${path}`);
    return route.fulfill({
      status: 404,
      json: { detail: "Unexpected synthetic route" },
    });
  });
  await page.goto("/workspace/datasets");
  await page
    .getByRole("combobox", { name: "Select project", exact: true })
    .selectOption(receipt.project_id);
  await expect(panel(page)).toBeVisible();
  expect(
    requests.filter((s) => /\/exports|export-capabilities|\/plans\//.test(s)),
  ).toEqual([]);
  return { requests, forbidden };
}
async function prepare(region: Locator) {
  const create = region.getByRole("button", { name: createLabel, exact: true });
  await expect(create).toBeDisabled();
  await region
    .getByRole("button", { name: "Load export policy and grants", exact: true })
    .click();
  const grant = region.getByRole("combobox", {
    name: "Exact export grant",
    exact: true,
  });
  await expect(grant).toHaveValue("");
  await grant.selectOption(receipt.grant.id);
  await region
    .getByRole("button", { name: "Open selected frozen plan", exact: true })
    .click();
  for (const [index, name] of consents.entries()) {
    await expect(create).toBeDisabled();
    await region.getByRole("checkbox", { name, exact: true }).check();
    if (index < 2) await expect(create).toBeDisabled();
  }
  await expect(create).toBeEnabled();
  return create;
}
for (const width of [1440, 390])
  test(`authorized configuration uses explicit consents and exact API ZIP at ${width}px`, async ({
    page,
  }) => {
    await page.setViewportSize({ width, height: 950 });
    const { requests, forbidden } = await setup(page),
      region = panel(page);
    const create = await prepare(region);
    await create.focus();
    await page.keyboard.press("Enter");
    await expect(
      region.getByText("Historical configuration receipt — NOT_EVALUATED", {
        exact: true,
      }),
    ).toBeVisible();
    const downloadButton = region.getByRole("button", {
      name: downloadLabel,
      exact: true,
    });
    await expect(downloadButton).toBeDisabled();
    expect(requests.filter((r) => r.includes("/bundle"))).toEqual([]);
    await region
      .getByRole("checkbox", { name: downloadConsent, exact: true })
      .check();
    await downloadButton.focus();
    const waiting = page.waitForEvent("download");
    await page.keyboard.press("Enter");
    const download = await waiting;
    expect(download.suggestedFilename()).toBe(`qa-config-${receipt.id}.zip`);
    const chunks: Buffer[] = [];
    for await (const chunk of await download.createReadStream())
      chunks.push(Buffer.from(chunk));
    expect(Buffer.concat(chunks)).toEqual(bundle);
    expect(requests.filter((r) => r.startsWith("PUT "))).toEqual([
      `PUT ${exportPath}`,
    ]);
    expect(requests.filter((r) => r.endsWith("/bundle"))).toEqual([
      `GET ${exportPath}/bundle`,
    ]);
    await expect(
      region.getByRole("checkbox", { name: downloadConsent, exact: true }),
    ).not.toBeChecked();
    expect(
      await page.evaluate(() => document.documentElement.scrollWidth),
    ).toBeLessThanOrEqual(width + 1);
    expect(forbidden).toEqual([]);
  });
test("unknown PUT and GET 404 retain only the same ID across project switches", async ({
  page,
}) => {
  const { forbidden } = await setup(page);
  let writes = 0,
    reads = 0;
  await page.route(`**${exportPath}`, (route) => {
    if (route.request().method() === "PUT") {
      writes++;
      expect(route.request().postDataJSON()).toEqual(fixture.request);
      return route.fulfill({
        status: 503,
        json: { detail: "Unknown delivery" },
      });
    }
    reads++;
    return reads === 1
      ? route.fulfill({ status: 404, json: { detail: "Not yet known" } })
      : route.fulfill({ json: receipt });
  });
  await (await prepare(panel(page))).click();
  await expect(panel(page).getByRole("status")).toContainText(receipt.id);
  await panel(page)
    .getByRole("button", { name: reconcileLabel, exact: true })
    .click();
  await expect(panel(page).getByRole("alert")).toBeVisible();
  await expect(panel(page).getByRole("status")).toContainText(receipt.id);
  await page
    .getByRole("combobox", { name: "Select project", exact: true })
    .selectOption("p2");
  await expect(panel(page).getByRole("status")).toHaveCount(0);
  await page
    .getByRole("combobox", { name: "Select project", exact: true })
    .selectOption(receipt.project_id);
  await expect(panel(page).getByRole("status")).toContainText(receipt.id);
  await expect(
    panel(page).getByRole("button", { name: createLabel, exact: true }),
  ).toBeDisabled();
  await panel(page)
    .getByRole("button", { name: reconcileLabel, exact: true })
    .click();
  await expect(panel(page).getByRole("status")).toHaveCount(0);
  await expect(
    panel(page).getByText("Historical configuration receipt — NOT_EVALUATED", {
      exact: true,
    }),
  ).toBeVisible();
  expect(writes).toBe(1);
  expect(reads).toBe(2);
  expect(forbidden).toEqual([]);
});
test("historical receipt opens without enabled policy and does not silently download", async ({
  page,
}) => {
  const { requests, forbidden } = await setup(page),
    region = panel(page);
  await page.route(`**${base}/export-capabilities`, (route) =>
    route.fulfill({
      json: {
        ...fixture.capabilities,
        enabled: false,
        grants: [],
        software_archive_sha256: null,
      },
    }),
  );
  await region
    .getByRole("textbox", { name: "Historical export ID", exact: true })
    .fill(receipt.id);
  await region
    .getByRole("button", { name: "Open exact export receipt", exact: true })
    .click();
  await expect(
    region.getByText("Historical configuration receipt — NOT_EVALUATED", {
      exact: true,
    }),
  ).toBeVisible();
  await region
    .getByRole("button", { name: "Load export policy and grants", exact: true })
    .click();
  await expect(
    region.getByRole("checkbox", { name: downloadConsent, exact: true }),
  ).toBeDisabled();
  await expect(
    region.getByRole("button", { name: downloadLabel, exact: true }),
  ).toBeDisabled();
  expect(requests.filter((r) => /\/bundle|^PUT /.test(r))).toEqual([]);
  expect(forbidden).toEqual([]);
});
test("a download error saves no file and never retries", async ({ page }) => {
  const { forbidden } = await setup(page),
    region = panel(page);
  let reads = 0;
  const saved: string[] = [];
  page.on("download", (download) => saved.push(download.suggestedFilename()));
  await page.route(`**${exportPath}/bundle?*`, (route) => {
    reads++;
    return route.fulfill({
      contentType: "text/html",
      body: "<h1>not a ZIP</h1>",
    });
  });
  await (await prepare(region)).click();
  await region
    .getByRole("checkbox", { name: downloadConsent, exact: true })
    .check();
  await region
    .getByRole("button", { name: downloadLabel, exact: true })
    .click();
  await expect(region.getByRole("alert")).toBeVisible();
  await expect(
    region.getByRole("button", { name: downloadLabel, exact: true }),
  ).toBeDisabled();
  expect(reads).toBe(1);
  expect(saved).toEqual([]);
  expect(forbidden).toEqual([]);
});
